package ai.wexa.benchmark;
import com.arangodb.*; import java.nio.file.*; import java.time.Instant; import java.util.*;
final class ArangoBenchmark {
 private final ArangoDB client; private final ArangoDatabase db;
 private ArangoBenchmark() throws Exception { client=ArangoConnection.connect(); String n=System.getenv().getOrDefault("ARANGO_DATABASE","benchmark"); try{client.createDatabase(n);}catch(Exception ignored){} db=client.db(n);try{db.createCollection("vertices");}catch(Exception ignored){}try{db.createCollection("edges");}catch(Exception ignored){} }
 private void q(String s,Map<String,?> p){try(ArangoCursor<Object> c=db.query(s,Object.class,p)){c.asListRemaining();}catch(Exception e){throw new RuntimeException(e);}}
 private void ingest(Main.Dataset d){for(int i=0;i<d.nodes().size();i+=1000){List<Map<String,Object>> r=new ArrayList<>();for(String id:d.nodes().subList(i,Math.min(i+1000,d.nodes().size())))r.add(Map.of("_key",id,"id",id));db.collection("vertices").insertDocuments(r);}for(int i=0;i<d.edges().size();i+=1000){List<Map<String,Object>> r=new ArrayList<>();for(Main.Edge e:d.edges().subList(i,Math.min(i+1000,d.edges().size())))r.add(Map.of("_from","vertices/"+e.source(),"_to","vertices/"+e.target(),"type","VOTED_FOR"));db.collection("edges").insertDocuments(r);}}
 private void trav(String id,int h){q("FOR e1 IN edges FILTER e1._from==@s "+(h>1?"FOR e2 IN edges FILTER e2._from==e1._to ":"")+(h>2?"FOR e3 IN edges FILTER e3._from==e2._to ":"")+"LIMIT 1000 RETURN 1",Map.of("s","vertices/"+id));}
 private double t(Runnable r){long s=System.nanoTime();r.run();return(System.nanoTime()-s)/1e6;}
 private double p(List<Double> a,double p){List<Double>x=new ArrayList<>(a);Collections.sort(x);return x.get((int)Math.ceil(x.size()*p)-1);}
 private double m(String n,List<String> ids,int i){String id=ids.get(i%ids.size());return t(()->{if(n.equals("pointLookup"))q("FOR v IN vertices FILTER v._key==@id RETURN v",Map.of("id",id));else if(n.equals("filteredLookup"))q("FOR v IN vertices FILTER STARTS_WITH(v.id,@p) LIMIT 25 RETURN v",Map.of("p",id.substring(0,1)));else if(n.equals("aggregation"))q("FOR e IN edges COLLECT type=e.type WITH COUNT INTO count RETURN {type,count}",Map.of());else trav(id,n.equals("oneHop")?1:n.equals("twoHop")?2:3);});}
 void work(Main.Dataset d)throws Exception{q("FOR x IN vertices REMOVE x IN vertices",Map.of());q("FOR x IN edges REMOVE x IN edges",Map.of());long ls=System.nanoTime();ingest(d);double load=(System.nanoTime()-ls)/1e6;List<String> ids=new ArrayList<>(d.nodes());Collections.shuffle(ids,new Random(42));Map<String,List<Double>> all=new LinkedHashMap<>();for(String n:List.of("oneHop","twoHop","threeHop","pointLookup","filteredLookup","aggregation")){all.put(n,new ArrayList<>());for(int i=0;i<20;i++)m(n,ids,i);for(int i=0;i<100;i++)all.get(n).add(m(n,ids,i));}long ms=System.nanoTime();for(int i=0;i<100;i++){String id=ids.get(i%ids.size());if(i%10==0)q("FOR v IN vertices FILTER v._key==@id UPDATE v WITH {lastBenchWrite:DATE_NOW()} IN vertices",Map.of("id",id));else trav(id,1);}double mixed=(System.nanoTime()-ms)/1e6;StringBuilder o=new StringBuilder("target=arangograph\nnodes=").append(d.nodes().size()).append(" relationships=").append(d.edges().size()).append(" loadMs=").append(load).append("\n");for(var e:all.entrySet())o.append(e.getKey()).append(" p50Ms=").append(p(e.getValue(),.5)).append(" p95Ms=").append(p(e.getValue(),.95)).append(" samples=100\n");o.append("mixedQps=").append(100/(mixed/1000)).append(" durationMs=").append(mixed).append("\n");Files.writeString(Path.of("results/arangograph-"+Instant.now().toEpochMilli()+".txt"),o.toString());}
 static void run(Main.Dataset d)throws Exception{ArangoBenchmark b=new ArangoBenchmark();try{b.work(d);}finally{b.client.shutdown();}}
}
